373	  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
374	  const avg7d = await db.select({ avg: sql<number>`AVG(${truthDriftTimeSeries.truthDriftScore})` })
375	    .from(truthDriftTimeSeries)
