/**
 * Map a geometry-runtime stateSnapshot (flat Record<string, number>) onto the
 * CanonicalEmotionalState the advanced neurocosmology hooks expect. Only the
 * base dimensions that exist in the canonical shape are mapped; derived
 * dimensions are recomputed by updateBaseDimensions.
 */
function buildCanonicalState(
  snapshot: Record<string, number> | undefined,
  sessionId: string,
  userId: string,
): CanonicalEmotionalState {
  return updateBaseDimensions(createInitialState(sessionId, userId), {
    emotionalMass: snapshot?.emotionalMass ?? 0,
    valenceCharge: snapshot?.emotionalValence ?? snapshot?.emotionalCharge ?? 0,
    attentionCurvature: snapshot?.attentionCurvature ?? 0,
    memoryEntropy: snapshot?.memoryEntropy ?? 0.5,
    relationalDistance: snapshot?.emotionalDistance ?? 1,
  });
}

function buildMessages(params: GovernedGenerateParams, contextInjection?: string): InvokeParams['messages'] {
  const messages: Message[] = [];

  // Add system prompt if provided
  if (params.systemPrompt) {
    messages.push({ role: 'system', content: params.systemPrompt });
  }

  // Add product-aware governance context injection (from resolveGovernanceContext)
  const governanceContext = contextInjection || buildGovernanceContextString(params);
  if (governanceContext) {
    const existingSystem = messages.find((m) => m.role === 'system');
    if (existingSystem) {
      existingSystem.content = governanceContext + '\n\n' + existingSystem.content;
    } else {
      messages.push({ role: 'system', content: governanceContext });
    }
  }

  // Add the actual messages
  if (params.messages) {
    for (const msg of params.messages) {
      // Skip system messages if we already injected one
      if (msg.role === 'system' && messages.some(m => m.role === 'system')) {
        const systemMsg = messages.find(m => m.role === 'system');
        if (systemMsg) {
          systemMsg.content += '\n\n' + (typeof msg.content === 'string' ? msg.content : '');
        }
      } else {
        messages.push(msg);
      }
    }
  }

  return messages;
}

function buildGovernanceContextString(params: GovernedGenerateParams): string {
  const parts: string[] = [];

  if (params.contentRole === 'user-facing') {
    parts.push('[GOVERNANCE] This content is user-facing. Apply full governance checks.');
  }
  if (params.audienceType === 'medical') {
    parts.push('[GOVERNANCE] Medical content — include appropriate disclaimers. Do not provide medical advice.');
  }
  if (params.audienceType === 'legal') {
    parts.push('[GOVERNANCE] Legal content — include appropriate disclaimers. Do not provide legal advice.');
  }
  if (params.contentType === 'marketing') {
    parts.push('[GOVERNANCE] Marketing content — avoid misleading claims. Be factual and verifiable.');
  }

  return parts.length > 0 ? parts.join('\n') : '';
}

function extractContent(result: InvokeResult): string {
  const content = result?.choices?.[0]?.message?.content;
  if (!content) return '';
  return typeof content === 'string' ? content : JSON.stringify(content);
}

function updateMetrics(
  result: GovernedGenerateResult,
  productKey: string,
  startTime: number,
): void {
  const latency = Date.now() - startTime;
  _metrics.avgLatencyMs = ((_metrics.avgLatencyMs * (_metrics.totalCalls - 1)) + latency) / _metrics.totalCalls;

  switch (result.decision) {
    case 'pass': _metrics.totalPassed++; break;
    case 'stabilize': _metrics.totalStabilized++; break;
    case 'block':
      _metrics.totalBlocked++;
      _metrics.byProduct[productKey].blocked++;
      break;
    case 'regenerate': _metrics.totalRegenerated++; break;
  }
}

/**
 * Reset metrics (for testing).
 */
export function resetGovernedGenerateMetrics(): void {
  _metrics.totalCalls = 0;
  _metrics.totalPassed = 0;
  _metrics.totalStabilized = 0;
  _metrics.totalBlocked = 0;
  _metrics.totalRegenerated = 0;
  _metrics.totalDegraded = 0;
  _metrics.totalErrors = 0;
  _metrics.avgLatencyMs = 0;
  _metrics.byProduct = {};
}

