/**
 * Organizational Memory Service — Phase 5
 * 
 * Cross-surface learning, historical drift models, and persona alignment.
 * This is the "intelligence" layer that makes the governance engine smarter over time.
 */

import { getDb } from '../db';
import { violationPatterns, truthDriftTimeSeries, personaAlignmentMap } from '../../drizzle/schema';
import { eq, desc, and, sql } from 'drizzle-orm';
import { governedGenerate } from "../governance/governed-generate";
import { generalLog } from '../_core/logger';

// ============================================================================
// CROSS-SURFACE LEARNING
// ============================================================================

interface ViolationEvent {
  violationType: string;
  surface: string;
  route: string;
  severity: string;
  content?: string;
}

/**
 * Record a violation event and update pattern tracking.
 * Called after every scan to build the learning model.
 */
export async function recordViolationPattern(event: ViolationEvent): Promise<void> {
  const patternKey = `${event.violationType}::${event.surface}`;

  const db = await getDb();
  if (!db) throw new Error('Database not available');
  // Check if pattern already exists
  const existing = await db.select()
    .from(violationPatterns)
    .where(
      and(
        eq(violationPatterns.violationType, event.violationType),
        eq(violationPatterns.surface, event.surface),
      )
    )
    .limit(1);

  if (existing.length > 0) {
    // Update existing pattern
    await db.update(violationPatterns)
      .set({
        lastSeen: new Date(),
        occurrenceCount: sql`${violationPatterns.occurrenceCount} + 1`,
        route: event.route, // Update to latest route
        avgSeverity: event.severity,
        commonContent: event.content?.substring(0, 500) || existing[0].commonContent,
        updatedAt: new Date(),
      })
      .where(eq(violationPatterns.id, existing[0].id));
  } else {
    // Create new pattern
    const patternId = `pat_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
    await db.insert(violationPatterns).values({
      patternId,
      violationType: event.violationType,
      surface: event.surface,
      route: event.route,
      occurrenceCount: 1,
      avgSeverity: event.severity,
      commonContent: event.content?.substring(0, 500),
    });
  }
}

/**
 * Record resolution of a violation (auto-fixed, manual, or reverted).
 */
export async function recordPatternResolution(
  violationType: string,
  surface: string,
  resolution: 'auto_fixed' | 'manual_fixed' | 'reverted',
): Promise<void> {
  const db = await getDb();
  if (!db) return;
  const existing = await db.select()
    .from(violationPatterns)
    .where(
      and(
        eq(violationPatterns.violationType, violationType),
        eq(violationPatterns.surface, surface),
      )
    )
    .limit(1);

  if (existing.length > 0) {
    const updates: Record<string, unknown> = { updatedAt: new Date() };
    if (resolution === 'auto_fixed') {
      updates.autoFixedCount = sql`${violationPatterns.autoFixedCount} + 1`;
    } else if (resolution === 'manual_fixed') {
      updates.manualFixedCount = sql`${violationPatterns.manualFixedCount} + 1`;
    } else if (resolution === 'reverted') {
      updates.revertedCount = sql`${violationPatterns.revertedCount} + 1`;
    }
    await db.update(violationPatterns)
      .set(updates)
      .where(eq(violationPatterns.id, existing[0].id));
  }
}

/**
 * Batch-record violations from a scan report.
 */
export async function recordScanViolations(
  violations: Array<{ violationType: string; route: string; severity: string; content?: string }>,
  surface: string = 'website',
): Promise<{ patternsUpdated: number; newPatterns: number }> {
  let updated = 0;
  let created = 0;

  const db = await getDb();
  if (!db) return { patternsUpdated: 0, newPatterns: 0 };
  for (const v of violations) {
    const existing = await db.select()
      .from(violationPatterns)
      .where(
        and(
          eq(violationPatterns.violationType, v.violationType),
          eq(violationPatterns.surface, surface),
        )
      )
      .limit(1);

    if (existing.length > 0) {
      updated++;
    } else {
      created++;
    }

    await recordViolationPattern({
      violationType: v.violationType,
      surface,
      route: v.route,
      severity: v.severity,
      content: v.content,
    });
  }

  return { patternsUpdated: updated, newPatterns: created };
}

/**
 * Get the top recurring violation patterns across all surfaces.
 */
export async function getTopPatterns(limit: number = 10): Promise<Array<{
  violationType: string;
  surface: string;
  occurrenceCount: number;
  autoFixedCount: number;
  manualFixedCount: number;
  revertedCount: number;
  avgSeverity: string | null;
  firstSeen: Date;
  lastSeen: Date;
  suggestedPrevention: string | null;
}>> {
  const db = await getDb();
  if (!db) return [];
  const patterns = await db.select()
    .from(violationPatterns)
    .orderBy(desc(violationPatterns.occurrenceCount))
    .limit(limit);

  return patterns.map(p => ({
    violationType: p.violationType,
    surface: p.surface,
    occurrenceCount: p.occurrenceCount,
    autoFixedCount: p.autoFixedCount,
    manualFixedCount: p.manualFixedCount,
    revertedCount: p.revertedCount,
    avgSeverity: p.avgSeverity,
    firstSeen: p.firstSeen,
    lastSeen: p.lastSeen,
    suggestedPrevention: p.suggestedPrevention,
  }));
}

/**
 * Generate prevention advice for a pattern using Claude.
 */
export async function generatePreventionAdvice(patternId: string): Promise<string> {
  const db = await getDb();
  if (!db) return 'Database not available.';
  const pattern = await db.select()
    .from(violationPatterns)
    .where(eq(violationPatterns.patternId, patternId))
    .limit(1);

  if (pattern.length === 0) return 'Pattern not found.';

  const p = pattern[0];
  const govResult = await governedGenerate({
    messages: [
      {
        role: 'system',
        content: 'You are a governance advisor. Given a recurring violation pattern, suggest a concrete prevention strategy in 2-3 sentences.',
      },
      {
        role: 'user',
        content: `Violation type: ${p.violationType}\nSurface: ${p.surface}\nOccurrences: ${p.occurrenceCount}\nAuto-fixed: ${p.autoFixedCount}\nManual-fixed: ${p.manualFixedCount}\nReverted: ${p.revertedCount}\nSample content: ${p.commonContent || 'N/A'}\n\nWhat should be done to prevent this from recurring?`,
      },
    ],
    contentType: 'generation',
    contentRole: 'user-facing',
    productId: 'services',
    surfaceId: 'services-organizational-memory',
  });

  // governedGenerate returns the post-governance text on `content` —
  // GovernedGenerateResult has no raw `choices[]` envelope.
  const advice = govResult.content || 'Unable to generate advice.';

  // Persist the advice
  await db.update(violationPatterns)
    .set({ suggestedPrevention: advice, updatedAt: new Date() })
    .where(eq(violationPatterns.patternId, patternId));

  return advice;
}

// ============================================================================
// HISTORICAL DRIFT MODEL
// ============================================================================

interface DriftSnapshot {
  scanId?: string;
  truthDriftScore: number;
  totalPages: number;
  passedPages: number;
  flaggedPages: number;
  blockedPages: number;
  totalViolations: number;
  criticalViolations: number;
  violationsByType?: Record<string, number>;
  autoAppliedCount?: number;
  queuedCount?: number;
  revertedCount?: number;
  activeProfile?: string;
  autoApplyEnabled?: boolean;
}

/**
 * Record a truth-drift snapshot after a scan.
 * Automatically calculates trend and delta from previous snapshot.
 */
export async function recordDriftSnapshot(snapshot: DriftSnapshot): Promise<{
  snapshotId: string;
  trend: string;
  delta: number | null;
}> {
  const db = await getDb();
  if (!db) return { snapshotId: '', trend: 'unknown', delta: null };
  // Get previous snapshot for trend calculation
  const previous = await db.select()
    .from(truthDriftTimeSeries)
    .orderBy(desc(truthDriftTimeSeries.capturedAt))
    .limit(1);

  const previousScore = previous.length > 0 ? previous[0].truthDriftScore : null;
  let trend = 'stable';
  let delta: number | null = null;

  if (previousScore !== null) {
    delta = snapshot.truthDriftScore - previousScore;
    if (delta > 2) trend = 'improving';
    else if (delta < -2) trend = 'declining';
    else trend = 'stable';
  }

  const snapshotId = `drift_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;

  await db.insert(truthDriftTimeSeries).values({
    snapshotId,
    scanId: snapshot.scanId,
    truthDriftScore: snapshot.truthDriftScore,
    totalPages: snapshot.totalPages,
    passedPages: snapshot.passedPages,
    flaggedPages: snapshot.flaggedPages,
    blockedPages: snapshot.blockedPages,
    totalViolations: snapshot.totalViolations,
    criticalViolations: snapshot.criticalViolations,
    violationsByType: snapshot.violationsByType,
    autoAppliedCount: snapshot.autoAppliedCount || 0,
    queuedCount: snapshot.queuedCount || 0,
    revertedCount: snapshot.revertedCount || 0,
    previousScore: previousScore,
    trend,
    weekOverWeekDelta: delta,
    activeProfile: snapshot.activeProfile,
    autoApplyEnabled: snapshot.autoApplyEnabled,
  });

  return { snapshotId, trend, delta };
}

/**
 * Get drift history for trend visualization.
 */
export async function getDriftHistory(limit: number = 30): Promise<Array<{
  snapshotId: string;
  truthDriftScore: number;
  trend: string | null;
  weekOverWeekDelta: number | null;
  totalViolations: number;
  autoAppliedCount: number;
  capturedAt: Date;
}>> {
  const db = await getDb();
  if (!db) return [];
  const history = await db.select()
    .from(truthDriftTimeSeries)
    .orderBy(desc(truthDriftTimeSeries.capturedAt))
    .limit(limit);

  return history.map(h => ({
    snapshotId: h.snapshotId,
    truthDriftScore: h.truthDriftScore,
    trend: h.trend,
    weekOverWeekDelta: h.weekOverWeekDelta,
    totalViolations: h.totalViolations,
    autoAppliedCount: h.autoAppliedCount,
    capturedAt: h.capturedAt,
  }));
}

/**
 * Get the current drift trend summary.
 */
export async function getDriftTrendSummary(): Promise<{
  currentScore: number | null;
  trend: string;
  weekOverWeekDelta: number | null;
  snapshotsCount: number;
  avgScore7d: number | null;
  avgScore30d: number | null;
}> {
  const db = await getDb();
  if (!db) return {
    currentScore: null,
    trend: 'unknown',
    weekOverWeekDelta: null,
    snapshotsCount: 0,
    avgScore7d: null,
    avgScore30d: null,
  };
  const latest = await db.select()
    .from(truthDriftTimeSeries)
    .orderBy(desc(truthDriftTimeSeries.capturedAt))
    .limit(1);

  if (latest.length === 0) {
    return {
      currentScore: null,
      trend: 'unknown',
      weekOverWeekDelta: null,
      snapshotsCount: 0,
      avgScore7d: null,
      avgScore30d: null,
    };
  }

  // Count total snapshots
  const countResult = await db.select({ count: sql<number>`count(*)` })
    .from(truthDriftTimeSeries);

  // Get 7-day average
  const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
  const avg7d = await db.select({ avg: sql<number>`AVG(${truthDriftTimeSeries.truthDriftScore})` })
    .from(truthDriftTimeSeries)
    .where(sql`${truthDriftTimeSeries.capturedAt} >= ${sevenDaysAgo}`);

  // Get 30-day average
  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
  const avg30d = await db.select({ avg: sql<number>`AVG(${truthDriftTimeSeries.truthDriftScore})` })
    .from(truthDriftTimeSeries)
    .where(sql`${truthDriftTimeSeries.capturedAt} >= ${thirtyDaysAgo}`);

  return {
    currentScore: latest[0].truthDriftScore,
    trend: latest[0].trend || 'stable',
    weekOverWeekDelta: latest[0].weekOverWeekDelta,
    snapshotsCount: countResult[0]?.count || 0,
    avgScore7d: avg7d[0]?.avg ? Math.round(avg7d[0].avg) : null,
    avgScore30d: avg30d[0]?.avg ? Math.round(avg30d[0].avg) : null,
  };
}

// ============================================================================
// PERSONA ALIGNMENT
// ============================================================================

interface PersonaConfig {
  surface: string;
  route?: string;
  targetPersona: string;
  expectedTone?: string;
  expectedFormality?: string;
  maxReadingLevel?: string;
  preferredTerms?: string[];
  avoidTerms?: string[];
}

/**
 * Set or update persona alignment for a surface/route.
 */
export async function setPersonaAlignment(config: PersonaConfig): Promise<string> {
  const db = await getDb();
  if (!db) return 'Database not available';
  const existing = await db.select()
    .from(personaAlignmentMap)
    .where(
      and(
        eq(personaAlignmentMap.surface, config.surface),
        eq(personaAlignmentMap.targetPersona, config.targetPersona),
        config.route
          ? eq(personaAlignmentMap.route, config.route)
          : sql`${personaAlignmentMap.route} IS NULL`,
      )
    )
    .limit(1);

  if (existing.length > 0) {
    await db.update(personaAlignmentMap)
      .set({
        expectedTone: config.expectedTone || existing[0].expectedTone,
        expectedFormality: config.expectedFormality || existing[0].expectedFormality,
        maxReadingLevel: config.maxReadingLevel || existing[0].maxReadingLevel,
        preferredTerms: config.preferredTerms || existing[0].preferredTerms,
        avoidTerms: config.avoidTerms || existing[0].avoidTerms,
        updatedAt: new Date(),
      })
      .where(eq(personaAlignmentMap.id, existing[0].id));
    return existing[0].alignmentId;
  }

  const alignmentId = `align_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
  await db.insert(personaAlignmentMap).values({
    alignmentId,
    surface: config.surface,
    route: config.route,
    targetPersona: config.targetPersona,
    expectedTone: config.expectedTone,
    expectedFormality: config.expectedFormality,
    maxReadingLevel: config.maxReadingLevel,
    preferredTerms: config.preferredTerms,
    avoidTerms: config.avoidTerms,
  });

  return alignmentId;
}

/**
 * Get persona alignment config for a specific surface/route.
 */
export async function getPersonaAlignment(
  surface: string,
  route?: string,
): Promise<Array<{
  alignmentId: string;
  targetPersona: string;
  expectedTone: string | null;
  expectedFormality: string | null;
  maxReadingLevel: string | null;
  preferredTerms: string[] | null;
  avoidTerms: string[] | null;
  lastAlignmentScore: number | null;
}>> {
  const db = await getDb();
  if (!db) return [];
  const conditions = [eq(personaAlignmentMap.surface, surface)];
  if (route) {
    conditions.push(eq(personaAlignmentMap.route, route));
  }

  const alignments = await db.select()
    .from(personaAlignmentMap)
    .where(and(...conditions)) ;

  if (!Array.isArray(alignments)) return [];

  return alignments.map(a => ({
    alignmentId: a.alignmentId,
    targetPersona: a.targetPersona,
    expectedTone: a.expectedTone,
    expectedFormality: a.expectedFormality,
    maxReadingLevel: a.maxReadingLevel,
    preferredTerms: a.preferredTerms,
    avoidTerms: a.avoidTerms,
    lastAlignmentScore: a.lastAlignmentScore,
  }));
}

/**
 * Evaluate content against persona alignment using Claude.
 */
export async function evaluatePersonaAlignment(
  content: string,
  surface: string,
  route?: string,
): Promise<{
  score: number;
  persona: string;
  feedback: string;
  toneMatch: boolean;
  formalityMatch: boolean;
}> {
  const alignments = await getPersonaAlignment(surface, route);

  if (alignments.length === 0) {
    return {
      score: 100,
      persona: 'unspecified',
      feedback: 'No persona alignment configured for this surface.',
      toneMatch: true,
      formalityMatch: true,
    };
  }

  const alignment = alignments[0];

  const govResult = await governedGenerate({
    messages: [
      {
        role: 'system',
        content: `You are a content alignment evaluator. Evaluate the content against the target persona profile and return JSON.`,
      },
      {
        role: 'user',
        content: `Target persona: ${alignment.targetPersona}
Expected tone: ${alignment.expectedTone || 'any'}
Expected formality: ${alignment.expectedFormality || 'any'}
Max reading level: ${alignment.maxReadingLevel || 'any'}
Preferred terms: ${(alignment.preferredTerms || []).join(', ') || 'none specified'}
Avoid terms: ${(alignment.avoidTerms || []).join(', ') || 'none specified'}

Content to evaluate:
${content.substring(0, 2000)}

Return JSON: { "score": 0-100, "toneMatch": true/false, "formalityMatch": true/false, "feedback": "brief assessment" }`,
      },
    ],
    response_format: {
      type: 'json_schema',
      json_schema: {
        name: 'persona_evaluation',
        strict: true,
        schema: {
          type: 'object',
          properties: {
            score: { type: 'integer', description: 'Alignment score 0-100' },
            toneMatch: { type: 'boolean', description: 'Does tone match expected?' },
            formalityMatch: { type: 'boolean', description: 'Does formality match expected?' },
            feedback: { type: 'string', description: 'Brief assessment' },
          },
          required: ['score', 'toneMatch', 'formalityMatch', 'feedback'],
          additionalProperties: false,
        },
      },
    },
    contentType: 'generation',
    contentRole: 'user-facing',
    productId: 'services',
    surfaceId: 'services-organizational-memory-2',
  });

  try {
    // governedGenerate returns the post-governance text on `content` —
    // GovernedGenerateResult has no raw `choices[]` envelope. A blocked/empty
    // generation fails to parse and falls through to the catch below.
    const result: PersonaEvaluation = JSON.parse(govResult.content || '{}');

    // Update the alignment score
    const dbConn = await getDb();
    if (dbConn) await dbConn.update(personaAlignmentMap)
      .set({
        lastAlignmentScore: result.score,
        lastEvaluatedAt: new Date(),
        updatedAt: new Date(),
      })
      .where(eq(personaAlignmentMap.alignmentId, alignment.alignmentId));

    return {
      score: result.score || 0,
      persona: alignment.targetPersona,
      feedback: result.feedback || 'No feedback generated.',
      toneMatch: result.toneMatch ?? true,
      formalityMatch: result.formalityMatch ?? true,
    };
  } catch {
    return {
      score: 50,
      persona: alignment.targetPersona,
      feedback: 'Evaluation failed — unable to parse govResult.',
      toneMatch: true,
      formalityMatch: true,
    };
  }
}

// ============================================================================
// INTEGRATION: Wire into scanner post-scan hook
// ============================================================================

/**
 * Post-scan hook: record all violations and drift snapshot.
 * Call this after every scan to build the organizational memory.
 */
export async function postScanMemoryUpdate(scanReport: {
  scanId: string;
  totalPages: number;
  passedPages: number;
  flaggedPages: number;
  blockedPages: number;
  totalViolations: number;
  criticalViolations: number;
  violations: Array<{ violationType: string; route: string; severity: string; content?: string }>;
  autoAppliedCount?: number;
  queuedCount?: number;
  activeProfile?: string;
  autoApplyEnabled?: boolean;
}): Promise<{
  patternsUpdated: number;
  newPatterns: number;
  driftSnapshot: { snapshotId: string; trend: string; delta: number | null };
}> {
  // 1. Record violation patterns for cross-surface learning
  const patternResult = await recordScanViolations(scanReport.violations, 'website');

  // 2. Calculate truth-drift score
  const truthDriftScore = scanReport.totalPages > 0
    ? Math.round((scanReport.passedPages / scanReport.totalPages) * 100)
    : 100;

  // 3. Build violation type breakdown
  const violationsByType: Record<string, number> = {};
  for (const v of scanReport.violations) {
    violationsByType[v.violationType] = (violationsByType[v.violationType] || 0) + 1;
  }

  // 4. Record drift snapshot
  const driftSnapshot = await recordDriftSnapshot({
    scanId: scanReport.scanId,
    truthDriftScore,
    totalPages: scanReport.totalPages,
    passedPages: scanReport.passedPages,
    flaggedPages: scanReport.flaggedPages,
    blockedPages: scanReport.blockedPages,
    totalViolations: scanReport.totalViolations,
    criticalViolations: scanReport.criticalViolations,
    violationsByType,
    autoAppliedCount: scanReport.autoAppliedCount || 0,
    queuedCount: scanReport.queuedCount || 0,
    activeProfile: scanReport.activeProfile,
    autoApplyEnabled: scanReport.autoApplyEnabled,
  });

  generalLog.info(`[OrgMemory] Post-scan update: ${patternResult.newPatterns} new patterns, ${patternResult.patternsUpdated} updated. Drift: ${truthDriftScore}% (${driftSnapshot.trend})`);

  return {
    ...patternResult,
    driftSnapshot,
  };
}

